const payload = $input.first().json.body || $input.first().json;

const companyName = 'Sri Meenakshi Traders';
const voucherType = (payload.voucherType || 'Sales').trim(); // Sales, Purchase, Receipt, Payment
const partyName = (payload.partyName || 'Cash Customer').trim();
const itemName = (payload.itemName || 'Electrical & Plumbing Material').trim();
const quantity = parseFloat(payload.quantity || 1);
const unit = payload.unit || 'Nos';
const rate = parseFloat(payload.rate || payload.price || 0);
const totalAmount = parseFloat(payload.amount || payload.total || (quantity * rate));
const narration = payload.narration || payload.notes || `Sales to ${partyName} via WhatsApp`;
const recipientJid = payload.replyJid || payload.remoteJid || '919361599097@s.whatsapp.net';

// Format date for Tally (YYYYMMDD) - Educational mode accepts 01, 02, 31
const now = new Date();
const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');
let day = String(now.getDate()).padStart(2, '0');
if (!['01', '02', '31'].includes(day)) {
  day = '01'; // Fallback to 1st of month for Educational Mode compatibility
}
const tallyDate = `${year}${month}${day}`;
const displayDate = `${day}-${month}-${year}`;

// Build XML for Sri Meenakshi Traders (Sales / Purchase / Receipt)
let xmlEnvelope = '';
if (voucherType === 'Sales') {
  xmlEnvelope = `<ENVELOPE>
  <HEADER><VERSION>1</VERSION><TALLYREQUEST>Import</TALLYREQUEST><TYPE>Data</TYPE><ID>Vouchers</ID></HEADER>
  <BODY>
    <DESC><STATICVARIABLES><SVCURRENTCOMPANY>${companyName}</SVCURRENTCOMPANY></STATICVARIABLES></DESC>
    <DATA>
      <TALLYMESSAGE xmlns:UDF="TallyUDF">
        <VOUCHER VCHTYPE="Sales" ACTION="Create">
          <DATE>${tallyDate}</DATE>
          <VOUCHERTYPENAME>Sales</VOUCHERTYPENAME>
          <PARTYLEDGERNAME>${partyName}</PARTYLEDGERNAME>
          <NARRATION>${narration} [Item: ${itemName} Qty: ${quantity} ${unit} @ Rs.${rate}]</NARRATION>
          <ALLLEDGERENTRIES.LIST>
            <LEDGERNAME>${partyName}</LEDGERNAME>
            <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
            <AMOUNT>-${totalAmount.toFixed(2)}</AMOUNT>
          </ALLLEDGERENTRIES.LIST>
          <ALLLEDGERENTRIES.LIST>
            <LEDGERNAME>Sales</LEDGERNAME>
            <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
            <AMOUNT>${totalAmount.toFixed(2)}</AMOUNT>
          </ALLLEDGERENTRIES.LIST>
        </VOUCHER>
      </TALLYMESSAGE>
    </DATA>
  </BODY>
</ENVELOPE>`;
} else {
  // Receipt / Payment fallback
  xmlEnvelope = `<ENVELOPE>
  <HEADER><VERSION>1</VERSION><TALLYREQUEST>Import</TALLYREQUEST><TYPE>Data</TYPE><ID>Vouchers</ID></HEADER>
  <BODY>
    <DESC><STATICVARIABLES><SVCURRENTCOMPANY>${companyName}</SVCURRENTCOMPANY></STATICVARIABLES></DESC>
    <DATA>
      <TALLYMESSAGE xmlns:UDF="TallyUDF">
        <VOUCHER VCHTYPE="Receipt" ACTION="Create">
          <DATE>${tallyDate}</DATE>
          <VOUCHERTYPENAME>Receipt</VOUCHERTYPENAME>
          <PARTYLEDGERNAME>${partyName}</PARTYLEDGERNAME>
          <NARRATION>${narration}</NARRATION>
          <ALLLEDGERENTRIES.LIST>
            <LEDGERNAME>${partyName}</LEDGERNAME>
            <ISDEEMEDPOSITIVE>No</ISDEEMEDPOSITIVE>
            <AMOUNT>${totalAmount.toFixed(2)}</AMOUNT>
          </ALLLEDGERENTRIES.LIST>
          <ALLLEDGERENTRIES.LIST>
            <LEDGERNAME>Cash</LEDGERNAME>
            <ISDEEMEDPOSITIVE>Yes</ISDEEMEDPOSITIVE>
            <AMOUNT>-${totalAmount.toFixed(2)}</AMOUNT>
          </ALLLEDGERENTRIES.LIST>
        </VOUCHER>
      </TALLYMESSAGE>
    </DATA>
  </BODY>
</ENVELOPE>`;
}

// Tamil WhatsApp Invoice Summary
const confirmationText = `🏪 *${companyName} (SMT) - Tally பில் பதிவானது!*\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📄 *பில் வகை:* ${voucherType} Voucher\n` +
  `👤 *வாடிக்கையாளர் / பார்ட்டி:* ${partyName}\n` +
  `📦 *பொருள்:* ${itemName}\n` +
  `🔢 *அளவு:* ${quantity} ${unit} (1 ${unit} = ₹${rate.toLocaleString('en-IN')})\n` +
  `💰 *மொத்தத் தொகை:* ₹${totalAmount.toLocaleString('en-IN')}\n` +
  `📅 *தேதி:* ${displayDate}\n` +
  `📝 *குறிப்பு:* ${narration}\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `_Tally Prime & SMT Google Sheet-ல் உடனடியாகப் பதிவானது._`;

return [{
  json: {
    companyName,
    voucherType,
    partyName,
    itemName,
    quantity,
    unit,
    rate,
    totalAmount,
    narration,
    recipientJid,
    tallyDate,
    displayDate,
    xmlEnvelope,
    confirmationText
  }
}];
